import{_ as p,l as s,o as e,c as i,v as t,p as n,x as r,d as l,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"两阶段提交","description":"","frontmatter":{"title":"两阶段提交","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/two-pc.md","filePath":"cs/two-pc.md","lastUpdated":1789023840000}'),m={name:"cs/two-pc.md"};function h(_,a,A,C,E,P){const o=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="两阶段提交" tabindex="-1">两阶段提交 <a class="header-anchor" href="#两阶段提交" aria-label="Permalink to &quot;两阶段提交&quot;">​</a></h1><div class="epigraph"><p>先投票再决策：所有参与者同意才提交，否则全体撤；协调器的日志是分布式原子的支点。</p><footer>—— 据 Lampson and Sturgis；Gray, Notes on Database Operating Systems；Bernstein 对 2PC 的整理</footer></div><p><a href="/cs/wait-die">上一课</a>处理单库等待图。本课不重画环。缺口是：一次事务改了两个资源管理器（两库、库与消息队列），本地 ARIES 只能保证各自 A/D，不能保证<strong>一起</strong>提交或一起撤。两阶段提交（2PC）加一个协调器：准备阶段锁住并记下「可提交」，提交阶段统一决策。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>本地 commit 记录一刷盘，该节点已持久。若另一节点随后 abort，原子性跨节点失败。缺口不是再讲 WAL，而是协议：协调器收集 yes/no；全 yes 则发 commit，否则 abort。参与者在 prepared 状态必须等待决策，即使自己已经把 UNDO 信息钉在日志里——这是阻塞窗口，不是算法写错。</p><p><span class="marginnote">假设故障：宕机、丢消息，不是拜占庭。协调器自身崩溃必须靠其日志恢复决策，否则参与者永远 prepared。三阶段提交减阻塞，主干不替换 2PC 作为第一协议。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>阶段一：协调器写 prepare，问参与者。参与者若能保证以后既可 commit 也可 abort，则写 prepared 日志并答 yes。阶段二：协调器写全局 commit/abort 并通知。参与者按决策 REDO 或 UNDO，释放锁。本课不把 XA 接口细节当理论，只锁定这两次持久决策点。</p>',8)),(e(),n(c,null,{default:r(()=>[d(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E5%8D%8F%E8%B0%83%E5%99%A8%22%5D%20--%3E%20P%5B%22prepare%22%5D%0A%20%20P%20--%3E%20V%5B%22yes%20%2F%20no%22%5D%0A%20%20V%20--%3E%7C%22%E5%85%A8%20yes%22%7C%20COM%5B%22%E5%85%A8%E5%B1%80%20commit%22%5D%0A%20%20V%20--%3E%7C%22%E4%BB%BB%E4%B8%80%20no%22%7C%20AB%5B%22%E5%85%A8%E5%B1%80%20abort%22%5D%0A%20%20COM%20--%3E%20CIA%5B%22%E5%90%8E%E8%AF%BE%3A%20CIA%20%E4%B8%89%E5%85%83%E7%BB%84%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>2PC 给的是崩溃故障下的原子性，不是隔离：各节点内部仍用 2PL/MVCC。prepared 期间锁不放，跨节点死锁与阻塞会放大上一课的等待图。协调器日志丢失且未复制，会出现「不知道该提交还是撤」的启发式窗口——工程上靠复制协调器或人工。本课与<a href="/cs/tcp-handshake">网络</a>的可靠字节流不同：这里要的是全体一致的提交位，不是一条连接的字节序。</p><p>阶段一结束时参与者必须既能提交也能撤，所以 UNDO 信息与锁都还在。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>2PC 不防恶意节点，也不保密。正确提交的事务仍可能被旁路读走、被伪造端点——这正是安全课要从 CIA 另起的缺口。也不处理网络分区下的可用性格：CAP 式放松（Paxos 提交、Saga）是后话，不插入本栏主干为「下一课」。</p><p>参与者在 prepared 时崩溃，重启必须仍记得「我已答应」，否则全局原子性裂开——这仍是 WAL，只是多一个决策位。后课默认：分布式原子可以做到；保密、完整、认证尚未成为对象。</p><p>协调器是新的单点：它的日志丢了，参与者会卡在 prepared。复制协调器是工程补丁，不是 2PC 规格的一部分。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>2PC 给崩溃故障下的原子，不给拜占庭、不给保密。</p></li><li><p>后课 CIA：提交正确仍可泄密或被冒充。</p></li><li><p>单库死锁已处理；跨 RM 原子靠 2PC 的投票与决策日志。</p></li><li><p>prepared 阻塞是协议的一部分；假设崩溃不是拜占庭。</p></li><li><p>提交正确仍可能泄密或被冒充，缺口交给 CIA。</p></li><li><p>出处：Gray；Lampson and Sturgis；Bernstein, Hadzilacos and Goodman。</p></li></ul>',9))])}const f=p(m,[["render",h]]);export{B as __pageData,f as default};
